def _private_key_for_version_locked(
    self, bucket: Dict[str, Any], did: str, version: int
) -> Optional[str]:
    rec = bucket["dids"].get(did) if bucket is not None else None
    if rec is None:
        return None
    for entry in rec.get("key_history", []):
        if entry.get("version") == version:
            return entry.get("private_key_pem")
    return None

@staticmethod
def _presentation_record(row: Dict[str, Any]) -> PresentationRecord:
    return PresentationRecord(
        presentation_id=row["presentation_id"],
        credential_id=row["credential_id"],
        issuer_did=row["issuer_did"],
        issuer_key_version=int(row["issuer_key_version"]),
        disclose=list(row.get("disclose", [])),
        projection=row.get("claims", {}),
        proof=row["proof"],
        challenge=row.get("challenge"),
        expires_at=row.get("expires_at"),
        holder_did=row.get("holder_did"),
        holder_key_version=(
            int(row["holder_key_version"])
            if row.get("holder_key_version") is not None
            else None
        ),
        holder_proof=row.get("holder_proof"),
    )

    ).hexdigest()


def _anchor_proof_build(
    leaf_hashes: List[str], index: int
) -> Tuple[str, List[Dict[str, str]]]:
    """以 cursor 升序叶序列对 index 处目标建 Merkle 包含证明。

    奇数层复制末项；返回 (root, path)，path 自叶向根，每项
    {"side": 兄弟所在侧, "hash": 兄弟哈希}。单叶时 root 即叶哈希、
    path 为空。
    """
    path: List[Dict[str, str]] = []
    level = list(leaf_hashes)
    current = index
    while len(level) > 1:
        if len(level) % 2 == 1:
            # 奇数末项复制后再配对。
            level.append(level[-1])
        if current % 2 == 0:
            path.append({"side": "right", "hash": level[current + 1]})
        else:
            path.append({"side": "left", "hash": level[current - 1]})
        next_level = [
            _anchor_proof_parent_hash(level[pos], level[pos + 1])
            for pos in range(0, len(level), 2)
        ]
        level = next_level
        current //= 2
    return level[0], path


def _anchor_proof_recompute_root(
    event_obj: Dict[str, Any], path: List[Dict[str, str]]
) -> str:
    """按 path 自叶向根重算 root（与建树同一叶/父哈希规则）。"""
    current = _anchor_proof_leaf_hash(event_obj)
    for item in path:
        sibling = item["hash"]
        if item["side"] == "left":
            current = _anchor_proof_parent_hash(sibling, current)
        else:
            current = _anchor_proof_parent_hash(current, sibling)
    return current


def build_handler(store: VCStore) -> type:
    """构造绑定给定 store 的请求处理器类。"""

    class Handler(BaseHTTPRequestHandler):
        server_version = "VCBackend/0.1"

        # ------------------------------------------------------------ #
        # 响应工具
        # ------------------------------------------------------------ #
        def _send_json(self, status: int, payload: Any) -> None:
            body = _json_dumps(payload)
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_error(self, status: int, message: str) -> None:
            self._send_json(status, {"error": message})

        def _send_invalid(self, reason: str) -> None:
            """verify 端点统一失败响应：HTTP 200 + valid:false + 中文原因。"""
            self._send_json(200, {"valid": False, "reason": reason})

        def _tenant_id(self) -> str:
            """解析 X-Tenant-ID：缺省 default；显式空串 400。"""
            raw = self.headers.get("X-Tenant-ID")
            if raw is None:
                return DEFAULT_TENANT
            if raw == "":
                raise ValidationError("X-Tenant-ID 不能为空")
            return raw

        def _read_json(self) -> Dict[str, Any]:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            try:
                data = json.loads(raw.decode("utf-8")) if raw else None
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        def _read_optional_json(self) -> Dict[str, Any]:
            """读取可选请求体：空体等价于 {}，非空时须为 JSON 对象。"""
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            if not raw:
                return {}
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        # ------------------------------------------------------------ #
        # 路由
        # ------------------------------------------------------------ #
        def do_POST(self) -> None:  # noqa: N802 (BaseHTTPRequestHandler API)
            try:
                parsed = urlparse(self.path)
                path = parsed.path.rstrip("/") or "/"
                parsed_query = parsed.query
                if not path.startswith("/v1"):
                    self._send_error(404, f"无此路径: {path}")
                    return
                tenant = self._tenant_id()
                if path == "/v1/dids":
                    self._post_dids(tenant)
                elif path == "/v1/credentials":
                    self._post_credentials(tenant)

def sync_credential_status_batch(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str, List[Dict[str, Any]]]:
    """批量同步外部凭证状态，返回 (请求是否合法, 请求级原因, 逐项结果)。

    请求体须恰为 ``{"items": [项...]}``：数组非空且不超过 100 项。
    请求级结构不合法（非对象、字段缺失或多余、items 非数组、空数组或
    超过上限）时返回 ``(False, "请求...", [])``，由调用方回
    ``{"results": [], "reason": ...}``；请求级非法不写任何状态。

    请求级合法时逐项复用 :meth:`sync_credential_status` 的完整单项
    规则（body 字段、锚点、签名、双键严格更新/重放/冲突与原子落盘），
    按输入顺序收集结果，**失败不短路**：某项的字段错误、锚点/签名
    失败或同秒冲突均不影响其余项。每项失败结果键序为
    ``valid,http_status,reason``（字段错误 400、同秒冲突 409、锚点/
    签名失败 200，reason 恒为非空中文）；成功结果键序为
    ``valid,http_status,issuer_did,credential_id,status,reason,
    updated_at,issuer_key_version``（首次 201，重放/更早日 200，
    严格更新 200 并记审计）。每个成功项沿用单项的状态/历史/审计
    同次原子写，落盘失败回滚该项，跨重启保持。results 与输入等长、
    同序。
    """
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象", []
    if set(data) != {"items"}:
        if "items" not in data:
            return False, "请求缺少字段: items", []
        extra = sorted(set(data) - {"items"})
        return False, f"请求含多余字段: {', '.join(extra)}", []
    items = data["items"]
    if not isinstance(items, list):
        return False, "请求不合法: 字段 items 必须为数组", []
    if not items:
        return False, "请求不合法: items 数组不能为空", []
    if len(items) > 100:
        return False, (
            f"请求不合法: items 数组不能超过 100 项（当前 {len(items)} 项）"
        ), []

    results: List[Dict[str, Any]] = []
    for item in items:  # 顺序处理，失败不短路
        try:
            result = self.sync_credential_status(tenant_id, item)
        except ValidationError as exc:
            results.append(
                {"valid": False, "http_status": 400, "reason": str(exc)}
            )
            continue
        except ConflictError as exc:
            results.append(
                {"valid": False, "http_status": 409, "reason": str(exc)}
            )
            continue
        if not result.get("valid"):
            results.append(
                {
                    "valid": False,
                    "http_status": 200,
                    "reason": result.get("reason") or "验签失败",
                }
            )
            continue
        record = result["record"]
        results.append(
            {
                "valid": True,
                "http_status": result["status_code"],
                "issuer_did": record.issuer_did,
                "credential_id": record.credential_id,
                "status": record.status,
                "reason": record.reason,
                "updated_at": record.updated_at,
                "issuer_key_version": record.issuer_key_version,
            }
        )
    return True, "", results

